try (java.io.ByteArrayOutputStream os = new java.io.ByteArrayOutputStream()) {
    net.coobird.thumbnailator.Thumbnails.of(sourceImage)
        .size(50, 50)
        .outputFormat("png")
        .toOutputStream(os);

    byte[] data = os.toByteArray();
    assert data.length > 0 : "Output stream should have written bytes";

    try (java.io.ByteArrayInputStream is = new java.io.ByteArrayInputStream(data)) {
        java.awt.image.BufferedImage result = javax.imageio.ImageIO.read(is);
        assert result != null : "Written data must be a valid image";
        assert result.getWidth() <= 50 && result.getHeight() <= 50 : "Thumbnail size must be bounded by 50x50";
        System.out.println("__CHECK__ toOutputStream " + data.length + " bytes, " + result.getWidth() + "x" + result.getHeight());
    }
}

